  Eval = "eval"
  Tick = "tick"
  Tock = "tock"
  TickTock = "ticktock"
  VmStep = "vmstep"
  Echo = "echo"
  Repeat = "repeat"
  ClearEcho = "clear-echo"
  Output = "output"
  OutputList = "output-list"
  FormatStyle = "B"|"D"|"S"|"X"
  ROM32K = "ROM32K"
  Load = "load"
  While = "while"
